INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Data Control Language dasselbe wie die Data Manipulation Language?', 2, '[{"text": "Nein", "correct": true, "because": "DCL regelt Zugriff, DML ändert Daten"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit DCL-Befehlen?', 3, '[{"text": "Zugriffsrechte verwalten", "correct": true, "because": "Sichert Datenbank"}, {"text": "Tabellen erstellen", "correct": false, "because": "Aufgabe von DDL"}, {"text": "Daten abfragen", "correct": false, "because": "DML-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle gehören zur DCL?', 5, '[{"text": "GRANT", "correct": true, "because": "Vergibt Rechte"}, {"text": "REVOKE", "correct": true, "because": "Entzieht Rechte"}, {"text": "SELECT", "correct": false, "because": "DML-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DCL steuert Berechtigungen. b) Sie ändert Daten direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenänderung ist DML"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DCL?', 4, '[{"text": "Rollenmanagement", "correct": false, "because": "Wichtig für Zugriff"}, {"text": "Sicherheitsrichtlinien", "correct": false, "because": "Basis der Steuerung"}, {"text": "Farbschema", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DCL Datenbankstrukturen ändert?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Zugriff, keine Struktur"}, {"text": "Ja", "correct": false, "because": "DDL macht das"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl gibt Zugriffsrechte?', 3, '[{"text": "GRANT", "correct": true, "because": "Vergibt Berechtigungen"}, {"text": "DENY", "correct": false, "because": "Verweigert Rechte"}, {"text": "INSERT", "correct": false, "because": "DML-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DCL?', 5, '[{"text": "Datensicherheit", "correct": true, "because": "Schützt vor unbefugtem Zugriff"}, {"text": "Rollenverwaltung", "correct": true, "because": "Vereinfacht Berechtigungen"}, {"text": "Datenänderung", "correct": false, "because": "Nicht DCL-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DCL ist für Administratoren. b) Sie erstellt Tabellen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tabellen sind DDL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DCL?', 4, '[{"text": "Benutzerkonten", "correct": false, "because": "Rechte werden vergeben"}, {"text": "Datenbankzugriff", "correct": false, "because": "Voraussetzung"}, {"text": "Grafiktreiber", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DCL für Datenmanipulation zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Das macht DML"}, {"text": "Ja", "correct": false, "because": "Nur Zugriffskontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte kann ich mit DCL vergeben?', 4, '[{"text": "Lesen", "correct": true, "because": "Zugriff auf Daten"}, {"text": "Schreiben", "correct": true, "because": "Änderung erlauben"}, {"text": "Tabellen löschen", "correct": false, "because": "DDL-Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DCL nur für große Datenbanken ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Größen relevant"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DCL?', 3, '[{"text": "Sicherheitskonzept", "correct": true, "because": "Schützt Daten"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Sicherheit zählt mehr"}, {"text": "Minimale Rechte", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DCL schützt Daten. b) Sie fragt Daten ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abfragen sind DML"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen unterstützt DCL?', 5, '[{"text": "Admin-Rechte", "correct": true, "because": "Vollzugriff möglich"}, {"text": "Lese-Rechte", "correct": true, "because": "Begrenzter Zugriff"}, {"text": "Datenbearbeitung", "correct": false, "because": "DML-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung unwichtig?', 3, '[{"text": "Zugriffssteuerung", "correct": false, "because": "Kern der DCL"}, {"text": "Benutzerrollen", "correct": false, "because": "Wichtig für Verwaltung"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DCL Tabellenstrukturen ändern?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Zugriff, keine Struktur"}, {"text": "Ja", "correct": false, "because": "DDL-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DCL in allen Datenbanken gleich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Syntax kann variieren"}, {"text": "Ja", "correct": false, "because": "DBMS-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat REVOKE?', 4, '[{"text": "Entzieht Rechte", "correct": true, "because": "Widerruft Zugriff"}, {"text": "Vergibt Rechte", "correct": false, "because": "Das macht GRANT"}, {"text": "Fragt Daten ab", "correct": false, "because": "DML-Bereich"}]');
